solution.javascript:
function planTournee(cadeaux, capacite, minimum, flotte) {
  if (cadeaux === 0) {
    return [];
  }
  const nb = Math.floor((cadeaux + capacite - 1) / capacite);
  if (nb > flotte) {
    return null;
  }
  const base = Math.floor(cadeaux / nb);
  const reste = cadeaux % nb;
  if (base < minimum) {
    return null;
  }
  const charges = [];
  for (let i = 0; i < nb; i++) {
    charges.push(i < reste ? base + 1 : base);
  }
  return charges;
}

solution.python:
def plan_tournee(cadeaux, capacite, minimum, flotte):
    if cadeaux == 0:
        return []
    nb = (cadeaux + capacite - 1) // capacite
    if nb > flotte:
        return None
    base = cadeaux // nb
    reste = cadeaux % nb
    if base < minimum:
        return None
    charges = []
    for i in range(nb):
        charges.append(base + 1 if i < reste else base)
    return charges

